import sys
from abc import ABC, abstractmethod

class Ticket(ABC):
    @abstractmethod
    def calculateFare(self, distance):
        pass

class BusTicket(Ticket):
    def calculateFare(self, distance):
        return distance * 5

class TrainTicket(Ticket):
    def calculateFare(self, distance):
        return distance * 8

class FlightTicket(Ticket):
    def calculateFare(self, distance):
        return distance * 15

def main():
    ticket_type = sys.stdin.readline().strip().lower()
    distance = int(sys.stdin.readline().strip())

    if ticket_type == 'bus':
        ticket = BusTicket()
        print("Ticket Type: Bus Ticket")
    elif ticket_type == 'train':
        ticket = TrainTicket()
        print("Ticket Type: Train Ticket")
    elif ticket_type == 'flight':
        ticket = FlightTicket()
        print("Ticket Type: Flight Ticket")

    fare = ticket.calculateFare(distance)
    print(f"Fare: {fare}")

if __name__ == "__main__":
    main()
